// TestSignStreamStub checks the methods, the constructors and the options
// of the double SignStreamStub.
func TestSignStreamStub(t *testing.T) {
	t.Parallel()

	t.Run("SignAndReset", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "SignAndReset", signStreamStubSignAndResetSubject)

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			var seen []cryptotest.SignStreamSignAndResetCall
			s.OnSignAndReset.OnRecord(func(c cryptotest.SignStreamSignAndResetCall) { seen = append(seen, c) })
			_, _ = signStreamStubSignAndReset(t, s)
			_, _ = signStreamStubSignAndReset(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of SignAndReset")
		})
	})

	t.Run("Write", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Write", signStreamStubWriteSubject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			_, _ = signStreamStubWrite(t, s)
			got := s.OnWrite.AssertCalledOnce(t, "Write records the call")
			a0 := signStreamStubWriteArgs(t)
			assert.Equal(t, got.P, a0, "the call records P")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			var seen []cryptotest.SignStreamWriteCall
			s.OnWrite.OnRecord(func(c cryptotest.SignStreamWriteCall) { seen = append(seen, c) })
			_, _ = signStreamStubWrite(t, s)
			_, _ = signStreamStubWrite(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Write")
		})
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()
		stub.ResetBehaviour(t, func(tb assert.TB) signStreamStubInstance {
			return signStreamStubInstanceOf(tb, cryptotest.NewSignStreamStub(tb))
		})

		t.Run("clears the recorded calls of SignAndReset", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			_, _ = signStreamStubSignAndReset(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnSignAndReset.CallCount(), 0, "ResetCalls clears the calls of SignAndReset")
		})

		t.Run("keeps the results of Returns of SignAndReset", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			want0, want1 := signStreamStubSignAndResetPins()
			s.OnSignAndReset.Returns(want0, want1)
			s.ResetCalls()
			got0, got1 := signStreamStubSignAndReset(t, s)
			expect.Equal(t, got0, want0, "ResetCalls keeps the Result of SignAndReset")
			expect.ErrorIs(t, got1, want1, "ResetCalls keeps the error of SignAndReset")
		})

		t.Run("clears the recorded calls of Write", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			_, _ = signStreamStubWrite(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnWrite.CallCount(), 0, "ResetCalls clears the calls of Write")
		})

		t.Run("keeps the results of Returns of Write", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			want0, want1 := signStreamStubWritePins()
			s.OnWrite.Returns(want0, want1)
			s.ResetCalls()
			got0, got1 := signStreamStubWrite(t, s)
			expect.Equal(t, got0, want0, "ResetCalls keeps the N of Write")
			expect.ErrorIs(t, got1, want1, "ResetCalls keeps the error of Write")
		})
	})

	t.Run("NewSignStreamStubDelayed", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) signStreamStubInstance {
			return signStreamStubInstanceOf(tb, cryptotest.NewSignStreamStubDelayed(tb, d, clk))
		})
	})

	t.Run("NewSignStreamStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails SignAndReset with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("SignAndReset-failing")
			s := cryptotest.NewSignStreamStubFailing(t, want)
			_, r1 := signStreamStubSignAndReset(t, s)
			assert.ErrorIs(t, r1, want, "SignAndReset fails with the error of NewSignStreamStubFailing")
		})

		t.Run("fails Write with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-failing")
			s := cryptotest.NewSignStreamStubFailing(t, want)
			_, err := signStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of NewSignStreamStubFailing")
		})
	})

	t.Run("SignStreamStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) signStreamStubInstance {
			return signStreamStubInstanceOf(tb, cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubStrict()))
		})
	})

	t.Run("SignStreamStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes SignAndReset to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewSignStreamStub(t)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, _ = signStreamStubSignAndReset(t, s)
			inner.OnSignAndReset.AssertCalledOnce(t, "SignAndReset calls the implementation")
		})

		t.Run("fails SignAndReset with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("SignAndReset-delegate")
			inner := cryptotest.NewSignStreamStub(t)
			inner.OnSignAndReset.Faults(want, 1)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, r1 := signStreamStubSignAndReset(t, s)
			assert.ErrorIs(t, r1, want, "SignAndReset fails with the error of the implementation")
		})

		t.Run("passes Write to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewSignStreamStub(t)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, _ = signStreamStubWrite(t, s)
			inner.OnWrite.AssertCalledOnce(t, "Write calls the implementation")
		})

		t.Run("fails Write with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-delegate")
			inner := cryptotest.NewSignStreamStub(t)
			inner.OnWrite.Faults(want, 1)
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubDelegateTo(inner))
			_, err := signStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of the implementation")
		})
	})

	t.Run("SignStreamStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) signStreamStubInstance {
			return signStreamStubInstanceOf(
				tb,
				cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubWithClock(clk)),
			)
		})
	})

	t.Run("SignStreamStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) signStreamStubInstance {
			return signStreamStubInstanceOf(
				tb,
				cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubWithRandSource(src)),
			)
		})
	})

	t.Run("SignStreamStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) signStreamStubInstance {
			return signStreamStubInstanceOf(tb, cryptotest.NewSignStreamStub(tb, cryptotest.SignStreamStubBenchMode()))
		})
	})

	t.Run("SignStreamStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) signStreamStubInstance {
			return signStreamStubInstanceOf(
				tb,
				cryptotest.NewSignStreamStub(
					tb,
					cryptotest.SignStreamStubWithClock(clk),
					cryptotest.SignStreamStubWithLatency(d),
				),
			)
		})
	})

	t.Run("SignStreamStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails SignAndReset with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("SignAndReset-failing")
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubFailing(want))
			_, r1 := signStreamStubSignAndReset(t, s)
			assert.ErrorIs(t, r1, want, "SignAndReset fails with the error of SignStreamStubFailing")
		})

		t.Run("fails Write with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-failing")
			s := cryptotest.NewSignStreamStub(t, cryptotest.SignStreamStubFailing(want))
			_, err := signStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of SignStreamStubFailing")
		})
	})

	t.Run("WithSignStreamSignAndReset", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of SignAndReset", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewSignStreamStub(t, cryptotest.WithSignStreamSignAndReset(func() ([]byte, error) {
				called = true
				var z0 []byte
				var z1 error
				return z0, z1
			}))
			_, _ = signStreamStubSignAndReset(t, s)
			assert.True(t, called, "WithSignStreamSignAndReset sets the function of SignAndReset")
		})
	})

	t.Run("WithSignStreamWrite", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Write", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewSignStreamStub(t, cryptotest.WithSignStreamWrite(func(_ []byte) (int, error) {
				called = true
				var z0 int
				var z1 error
				return z0, z1
			}))
			_, _ = signStreamStubWrite(t, s)
			assert.True(t, called, "WithSignStreamWrite sets the function of Write")
		})
	})
}

// TestSignStreamSignAndResetStub checks the methods of
// SignStreamSignAndResetStub, which configures SignAndReset.
func TestSignStreamSignAndResetStub(t *testing.T) {
	t.Parallel()

	t.Run("Returns", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the results of each call of SignAndReset", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewSignStreamStub(t)
			want0, want1 := signStreamStubSignAndResetPins()
			s.OnSignAndReset.Returns(want0, want1)
			got0, got1 := signStreamStubSignAndReset(t, s)
			expect.Equal(t, got0, want0, "SignAndReset returns the Result that Returns sets")
			expect.ErrorIs(t, got1, want1, "SignAndReset returns the error that Returns sets")
		})

		t.Run("configures SignAndReset for strict mode", func(t *testing.T) {
			t.Parallel()
			r := assert.NewRecorder()
			s := cryptotest.NewSignStreamStub(r)
			s.OnSignAndReset.Strict()
			var want0 []byte
			var want1 error
			s.OnSignAndReset.Returns(want0, want1)
			_, _ = signStreamStubSignAndReset(t, s)
			assert.False(t, r.Failed(), "strict mode accepts the call of SignAndReset")
		})
	})
}

