func verifyStreamStubWriteSubject(
	tb assert.TB,
) stub.Subject[cryptotest.VerifyStreamWriteCall, cryptotest.VerifyStreamWriteReturn] {
	tb.Helper()
	s := cryptotest.NewVerifyStreamStub(tb)
	return stub.Subject[cryptotest.VerifyStreamWriteCall, cryptotest.VerifyStreamWriteReturn]{
		Stub: s.OnWrite.MethodStub,
		Call: func() {
			_, _ = verifyStreamStubWrite(tb, s)
		},
		Result: func() cryptotest.VerifyStreamWriteReturn {
			got0, got1 := verifyStreamStubWrite(tb, s)
			return cryptotest.VerifyStreamWriteReturn{N: got0, Err: got1}
		},
		Override: func(mark func()) {
			s.OnWrite.Func(func(_ []byte) (int, error) {
				mark()
				var z0 int
				var z1 error
				return z0, z1
			})
		},
		Fails: func() error {
			_, err := verifyStreamStubWrite(tb, s)
			return err
		},
	}
}

// verifyStreamStubInstance is the instance of a
// cryptotest.VerifyStreamStub that the checks of the constructors and the
// options drive.
type verifyStreamStubInstance = stub.Instance[cryptotest.VerifyStreamVerifyCall]

// verifyStreamStubInstanceOf returns the instance of s. The options apply
// to the whole double, so the checks call Verify alone.
func verifyStreamStubInstanceOf(tb assert.TB, s *cryptotest.VerifyStreamStub) verifyStreamStubInstance {
	tb.Helper()
	return verifyStreamStubInstance{
		Stub: s.OnVerify.MethodStub,
		Call: func() {
			_ = verifyStreamStubVerify(tb, s)
		},
		Reset: s.ResetCalls,
	}
}

// TestVerifyStreamStub checks the methods, the constructors and the
// options of the double VerifyStreamStub.
func TestVerifyStreamStub(t *testing.T) {
	t.Parallel()

	t.Run("Verify", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Verify", verifyStreamStubVerifySubject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			_ = verifyStreamStubVerify(t, s)
			got := s.OnVerify.AssertCalledOnce(t, "Verify records the call")
			a0 := verifyStreamStubVerifyArgs(t)
			assert.Equal(t, got.Sig, a0, "the call records Sig")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			var seen []cryptotest.VerifyStreamVerifyCall
			s.OnVerify.OnRecord(func(c cryptotest.VerifyStreamVerifyCall) { seen = append(seen, c) })
			_ = verifyStreamStubVerify(t, s)
			_ = verifyStreamStubVerify(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Verify")
		})
	})

	t.Run("Write", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Write", verifyStreamStubWriteSubject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			_, _ = verifyStreamStubWrite(t, s)
			got := s.OnWrite.AssertCalledOnce(t, "Write records the call")
			a0 := verifyStreamStubWriteArgs(t)
			assert.Equal(t, got.P, a0, "the call records P")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			var seen []cryptotest.VerifyStreamWriteCall
			s.OnWrite.OnRecord(func(c cryptotest.VerifyStreamWriteCall) { seen = append(seen, c) })
			_, _ = verifyStreamStubWrite(t, s)
			_, _ = verifyStreamStubWrite(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Write")
		})
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()
		stub.ResetBehaviour(t, func(tb assert.TB) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(tb, cryptotest.NewVerifyStreamStub(tb))
		})

		t.Run("clears the recorded calls of Verify", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			_ = verifyStreamStubVerify(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnVerify.CallCount(), 0, "ResetCalls clears the calls of Verify")
		})

		t.Run("keeps the results of Returns of Verify", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			want0 := verifyStreamStubVerifyPins()
			s.OnVerify.Returns(want0)
			s.ResetCalls()
			got0 := verifyStreamStubVerify(t, s)
			assert.Equal(t, got0, want0, "ResetCalls keeps the Result of Verify")
		})

		t.Run("clears the recorded calls of Write", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			_, _ = verifyStreamStubWrite(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnWrite.CallCount(), 0, "ResetCalls clears the calls of Write")
		})

		t.Run("keeps the results of Returns of Write", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			want0, want1 := verifyStreamStubWritePins()
			s.OnWrite.Returns(want0, want1)
			s.ResetCalls()
			got0, got1 := verifyStreamStubWrite(t, s)
			expect.Equal(t, got0, want0, "ResetCalls keeps the N of Write")
			expect.ErrorIs(t, got1, want1, "ResetCalls keeps the error of Write")
		})
	})

	t.Run("NewVerifyStreamStubDelayed", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(tb, cryptotest.NewVerifyStreamStubDelayed(tb, d, clk))
		})
	})

	t.Run("NewVerifyStreamStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Write with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-failing")
			s := cryptotest.NewVerifyStreamStubFailing(t, want)
			_, err := verifyStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of NewVerifyStreamStubFailing")
		})
	})

	t.Run("VerifyStreamStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(
				tb,
				cryptotest.NewVerifyStreamStub(tb, cryptotest.VerifyStreamStubStrict()),
			)
		})
	})

	t.Run("VerifyStreamStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes Verify to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewVerifyStreamStub(t)
			s := cryptotest.NewVerifyStreamStub(t, cryptotest.VerifyStreamStubDelegateTo(inner))
			_ = verifyStreamStubVerify(t, s)
			inner.OnVerify.AssertCalledOnce(t, "Verify calls the implementation")
		})

		t.Run("passes Write to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewVerifyStreamStub(t)
			s := cryptotest.NewVerifyStreamStub(t, cryptotest.VerifyStreamStubDelegateTo(inner))
			_, _ = verifyStreamStubWrite(t, s)
			inner.OnWrite.AssertCalledOnce(t, "Write calls the implementation")
		})

		t.Run("fails Write with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-delegate")
			inner := cryptotest.NewVerifyStreamStub(t)
			inner.OnWrite.Faults(want, 1)
			s := cryptotest.NewVerifyStreamStub(t, cryptotest.VerifyStreamStubDelegateTo(inner))
			_, err := verifyStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of the implementation")
		})
	})

	t.Run("VerifyStreamStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(
				tb,
				cryptotest.NewVerifyStreamStub(tb, cryptotest.VerifyStreamStubWithClock(clk)),
			)
		})
	})

	t.Run("VerifyStreamStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(
				tb,
				cryptotest.NewVerifyStreamStub(tb, cryptotest.VerifyStreamStubWithRandSource(src)),
			)
		})
	})

	t.Run("VerifyStreamStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(
				tb,
				cryptotest.NewVerifyStreamStub(tb, cryptotest.VerifyStreamStubBenchMode()),
			)
		})
	})

	t.Run("VerifyStreamStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) verifyStreamStubInstance {
			return verifyStreamStubInstanceOf(
				tb,
				cryptotest.NewVerifyStreamStub(
					tb,
					cryptotest.VerifyStreamStubWithClock(clk),
					cryptotest.VerifyStreamStubWithLatency(d),
				),
			)
		})
	})

	t.Run("VerifyStreamStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Write with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Write-failing")
			s := cryptotest.NewVerifyStreamStub(t, cryptotest.VerifyStreamStubFailing(want))
			_, err := verifyStreamStubWrite(t, s)
			assert.ErrorIs(t, err, want, "Write fails with the error of VerifyStreamStubFailing")
		})
	})

	t.Run("WithVerifyStreamVerify", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Verify", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewVerifyStreamStub(t, cryptotest.WithVerifyStreamVerify(func(_ []byte) bool {
				called = true
				var z0 bool
				return z0
			}))
			_ = verifyStreamStubVerify(t, s)
			assert.True(t, called, "WithVerifyStreamVerify sets the function of Verify")
		})
	})

	t.Run("WithVerifyStreamWrite", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Write", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewVerifyStreamStub(t, cryptotest.WithVerifyStreamWrite(func(_ []byte) (int, error) {
				called = true
				var z0 int
				var z1 error
				return z0, z1
			}))
			_, _ = verifyStreamStubWrite(t, s)
			assert.True(t, called, "WithVerifyStreamWrite sets the function of Write")
		})
	})
}

// TestVerifyStreamVerifyStub checks the methods of VerifyStreamVerifyStub,
// which configures Verify.
func TestVerifyStreamVerifyStub(t *testing.T) {
	t.Parallel()

	t.Run("Returns", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the results of each call of Verify", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			want0 := verifyStreamStubVerifyPins()
			s.OnVerify.Returns(want0)
			got0 := verifyStreamStubVerify(t, s)
			assert.Equal(t, got0, want0, "Verify returns the Result that Returns sets")
		})

		t.Run("configures Verify for strict mode", func(t *testing.T) {
			t.Parallel()
			r := assert.NewRecorder()
			s := cryptotest.NewVerifyStreamStub(r)
			s.OnVerify.Strict()
			var want0 bool
			s.OnVerify.Returns(want0)
			_ = verifyStreamStubVerify(t, s)
			assert.False(t, r.Failed(), "strict mode accepts the call of Verify")
		})
	})

	t.Run("Func", func(t *testing.T) {
		t.Parallel()

		t.Run("passes the arguments of each call of Verify to the function", func(t *testing.T) {
			t.Parallel()
			s := cryptotest.NewVerifyStreamStub(t)
			var got0 []byte
			s.OnVerify.Func(func(p0 []byte) bool {
				got0 = p0
				var z0 bool
				return z0
			})
			_ = verifyStreamStubVerify(t, s)
			a0 := verifyStreamStubVerifyArgs(t)
			assert.Equal(t, got0, a0, "the function receives Sig")
		})
	})
}

